# GENERATED by `npx ray gen` from implementation/physics.ray - do not edit
#
# THE RUNTIME the emitted classes stand on (physics.R): what the recognised classes (N, String, Array, boolean) and the
# operators of Ray are in R.
#
# R copies a value when it is changed, so everything Ray shares is an environment, marked by `.t`:
#   "o" an object - its class (`.k`) and its own slots, a slot set to None holding the symbol NONE;
#   "c" a class   - a table of fields, getters, methods, statics and static fields, with a parent;
#   "l" a list    - an R list in `v`, so that a push is seen by everyone holding it (Ray counts from 0, R from 1);
#   "m" a Many    - a superposition: members apply elementwise, equal things collapse.
# Everything else is itself: NULL (None), a double (every number, as in the bootstrap), TRUE/FALSE, a character
# string, or a function (a program). A member is reached by name - `get(x, "cells")`, `call(x, "add", ...)`,
# `set(x, "tag", v)` - and found class by class up the chain (the nearest class declaring the name decides what it
# is, as a prototype chain does); what a name resolves to on a class is kept, so it is looked up once.

RT_TOP <- environment()
true <- TRUE
false <- FALSE
NONE <- quote(.none)
CONTINUE <- quote(.continue)

# --- classes and objects -----------------------------------------------------------------------------
table_ <- function() new.env(hash = TRUE, parent = emptyenv())
CLASSES <- table_()
THEORIES <- table_()

new_cls <- function(name, parent) {
  k <- table_()
  k$.t <- "c"
  k$.name <- name
  k$.parent <- parent
  k$.fields <- table_()
  k$.methods <- table_()
  k$.getters <- table_()
  k$.statics <- table_()
  k$.sdefaults <- table_()
  k$.sorder <- character()
  k$.order <- character()
  k$.gcache <- table_()
  k$.ccache <- table_()
  k$.scache <- table_()
  k
}
Node <- new_cls("Node", NULL)
assign("Node", Node, envir = CLASSES)

#' a class: its table, filled by `define` (the members the emitted code declares)
cls <- function(name, parent, define) {
  # the table is filled once: compiling the whole of it first would cost more than filling it (its members are compiled as they are used)
  jit <- compiler::enableJIT(0)
  on.exit(compiler::enableJIT(jit))
  k <- new_cls(name, parent)
  assign(name, k, envir = CLASSES)
  define(k)
  k
}
field <- function(cl, n, d) { assign(n, if (is.null(d)) NONE else d, envir = cl$.fields); cl$.order <- c(cl$.order, n); invisible(cl) }
method <- function(cl, n, m) { assign(n, m, envir = cl$.methods); invisible(cl) }
getter <- function(cl, n, g) { assign(n, g, envir = cl$.getters); invisible(cl) }
statik <- function(cl, n, s) { assign(n, s, envir = cl$.statics); invisible(cl) }
static_field <- function(cl, n, d) {
  if (!exists(n, envir = cl$.sdefaults, inherits = FALSE)) cl$.sorder <- c(cl$.sorder, n)
  assign(n, d, envir = cl$.sdefaults)
  invisible(cl)
}
has_ <- function(e, n) exists(n, envir = e, inherits = FALSE)
is_a <- function(k, c) { while (!is.null(k)) { if (identical(k, c)) return(TRUE); k <- k$.parent }; FALSE }
find_static <- function(c, n) {
  s <- c$.scache[[n]]
  if (!is.null(s)) return(if (is.function(s)) s else NULL)
  k <- c
  while (!is.null(k)) { s <- k$.statics[[n]]; if (!is.null(s)) break; k <- k$.parent }
  s <- if (is.null(s)) FALSE else cmp(s)
  assign(n, s, envir = c$.scache)
  if (is.function(s)) s else NULL
}
#' a member compiled when it is first used (the tables are filled uncompiled, which is what makes loading quick)
cmp <- function(f) tryCatch(compiler::cmpfun(f), error = function(e) f)
find_static_field <- function(c, n) { k <- c; while (!is.null(k)) { if (has_(k$.sdefaults, n) || has_(k, n)) return(k); k <- k$.parent }; NULL }
owner <- function(c, n) { k <- c; while (!is.null(k)) { if (has_(k$.getters, n) || has_(k$.fields, n) || has_(k$.methods, n)) return(k); k <- k$.parent }; NULL }
all_order <- function(c) { out <- character(); k <- c; while (!is.null(k)) { out <- c(k$.order, out); k <- k$.parent }; out }

#' a class by its name (`Boundary.Terminal` by its own), or a theory by its: what a class written in Ray is, as a value
K <- function(name) {
  v <- THEORIES[[name]]
  if (!is.null(v)) return(v)
  v <- CLASSES[[name]]
  if (!is.null(v)) return(v)
  n <- sub(".*\\.", "", name)
  v <- THEORIES[[n]]
  if (!is.null(v)) return(v)
  v <- CLASSES[[n]]
  if (is.null(v)) stop(paste0("no class ", name, " in this package"))
  v
}

new_obj <- function(c) { o <- table_(); o$.t <- "o"; o$.k <- c; o }
#' `Class(x: 1, ...)`: an object of the class, its named fields set (and the rest by position, in the order they are declared)
make <- function(.K, ...) {
  c <- if (is.environment(.K)) .K else K(.K)
  o <- new_obj(c)
  a <- list(...)
  if (length(a)) {
    nms <- names(a)
    if (is.null(nms)) nms <- character(length(a))
    order <- NULL
    positional <- 0
    for (i in seq_along(a)) {
      v <- a[[i]]
      if (is.null(v)) v <- NONE
      if (nzchar(nms[i])) assign(nms[i], v, envir = o)
      else {
        if (is.null(order)) order <- all_order(c)
        positional <- positional + 1
        if (positional <= length(order)) assign(order[positional], v, envir = o)
      }
    }
  }
  o
}

#' a theory: its class made once, its rules and theorems read off the class in the order they are written
theory <- function(c) {
  o <- new_obj(c)
  assign(c$.name, o, envir = THEORIES)
  chain <- list()
  k <- c
  while (!is.null(k)) { chain <- c(list(k), chain); k <- k$.parent }
  rules <- list()
  theorems <- list()
  for (k in chain) for (n in k$.sorder) {
    if (startsWith(n, "rule ")) rules[[length(rules) + 1]] <- get(c, n)
    else if (startsWith(n, "theorem ")) theorems[[length(theorems) + 1]] <- get(c, n)
  }
  assign("rules", as_list(rules), envir = o)
  assign("theorems", as_list(theorems), envir = o)
  o
}
#' a share of a term: its source, and the program that reads it at the symbols
at <- function(source, f) make(Node, source = source, at = function(s = NULL, ...) f(s))
#' a top-level definition: made on first read
lazy_constant <- function(f) {
  made <- FALSE
  v <- NULL
  function() {
    if (!made) { made <<- TRUE; v <<- f() }
    v
  }
}

# --- members by name ------------------------------------------------------------------------------
#' what reading `n` on an object of class `c` does, found once: a getter, a field (its default made on first read), a method (bound), a static
resolve_get <- function(c, n) {
  k <- owner(c, n)
  r <- NULL
  if (!is.null(k)) {
    g <- k$.getters[[n]]
    if (!is.null(g)) r <- cmp(g)
    else if (has_(k$.fields, n)) {
      d <- k$.fields[[n]]
      if (!is.symbol(d)) d <- cmp(d)
      r <- if (is.symbol(d)) function(o) { assign(n, NONE, envir = o); NULL }
           else function(o) { v <- d(o); assign(n, if (is.null(v)) NONE else v, envir = o); v }
    } else {
      m <- cmp(k$.methods[[n]])
      r <- function(o) function(...) m(o, ...)
    }
  } else r <- function(o) get_static(o$.k, n)
  assign(n, r, envir = c$.gcache)
  r
}
#' what calling `n` on an object of class `c` does, found once: its method, or whatever reading it gives, called
resolve_call <- function(c, n) {
  k <- owner(c, n)
  m <- if (is.null(k)) NULL else k$.methods[[n]]
  r <- if (!is.null(m)) cmp(m) else function(o, ...) {
    f <- get(o, n)
    if (is.function(f)) return(f(...))
    if (is.null(f)) stop(paste0("no method ", n, " on ", o$.k$.name))
    f
  }
  assign(n, r, envir = c$.ccache)
  r
}
get_static <- function(c, n) {
  k <- find_static_field(c, n)
  if (!is.null(k)) {
    v <- k[[n]]
    if (!is.null(v)) return(if (is.symbol(v)) NULL else v)
    v <- cmp(k$.sdefaults[[n]])(NULL)
    assign(n, if (is.null(v)) NONE else v, envir = k)
    return(v)
  }
  s <- find_static(c, n)
  if (!is.null(s)) return(s(NULL))
  NULL
}

#' `x.name`: a member by its name (and, called the way base R calls it, base R's `get`)
get <- function(t, n, ...) {
  if (is.environment(t)) {
    # an object's own slot, or a class's static already made: every other name the runtime keeps opens with a dot
    v <- t[[n]]
    if (!is.null(v)) return(if (is.symbol(v)) NULL else v)
    tt <- t$.t
    if (tt == "o") {
      g <- t$.k$.gcache[[n]]
      if (is.null(g)) g <- resolve_get(t$.k, n)
      return(g(t))
    }
    if (tt == "l") { if (n == "length") return(length(t$.v)); stop(paste0("no member ", n, " on a list")) }
    if (tt == "c") return(get_static(t, n))
    if (tt == "m") return(collapse(lapply(t$.i, function(x) if (is.null(x)) NULL else get(x, n))))
  }
  if (is.character(t) && (missing(n) || ...length() > 0 || !is.character(n))) return(base::get(t, ...))
  if (is.null(t)) stop(paste0("no member ", n, " on None"))
  if (n == "length") return(len(t))
  stop(paste0("no member ", n, " on ", typeof(t)))
}
get_opt <- function(t, n) if (is.null(t)) NULL else get(t, n)
#' `x.name = v`
set <- function(t, n, v) {
  force(v)
  tt <- if (is.environment(t)) t$.t else NULL
  if (tt == "o") assign(n, if (is.null(v)) NONE else v, envir = t)
  else if (tt == "c") { k <- find_static_field(t, n); assign(n, if (is.null(v)) NONE else v, envir = if (is.null(k)) t else k) }
  else if (tt == "m") for (x in t$.i) set(x, n, v)
  else stop(paste0("no member ", n, " to set on ", text_of(t)))
  invisible(v)
}
#' `x.name(args)` (and, called the way base R calls it, base R's `call`)
call <- function(t, n, ...) {
  if (is.environment(t)) {
    tt <- t$.t
    if (tt == "o") {
      v <- t[[n]]
      if (is.null(v)) {
        m <- t$.k$.ccache[[n]]
        if (is.null(m)) m <- resolve_call(t$.k, n)
        return(m(t, ...))
      }
      if (is.function(v)) return(v(...))
      if (is.symbol(v)) stop(paste0("no method ", n, " on ", t$.k$.name))
      return(v)
    }
    if (tt == "c") {
      s <- find_static(t, n)
      if (!is.null(s)) return(s(NULL, ...))
      f <- get_static(t, n)
      if (is.function(f)) return(f(...))
      stop(paste0("no static ", n, " on ", t$.name))
    }
    if (tt == "m") return(collapse(lapply(t$.i, function(x) call(x, n, ...))))
  }
  if (is.character(t) && (missing(n) || !is.character(n))) return(do.call(base::call, c(list(t), if (missing(n)) list() else list(n), list(...))))
  if (is.null(t)) stop(paste0("no method ", n, " on None"))
  stop(paste0("no method ", n, " on ", typeof(t)))
}
call_opt <- function(t, n, ...) if (is.null(t)) NULL else call(t, n, ...)
invoke <- function(f, ...) {
  if (is.function(f)) return(f(...))
  stop(paste0("not a program: ", text_of(f)))
}
choose_ <- function(t, name) get(t, paste0("choose ", name))
#' whether an object has a member of this name, of its own or its class's
has <- function(t, n) {
  if (!is.environment(t)) return(FALSE)
  tt <- t$.t
  if (tt == "o") return(!is.null(t[[n]]) || !is.null(owner(t$.k, n)))
  if (tt == "c") return(!is.null(find_static(t, n)) || !is.null(find_static_field(t, n)))
  FALSE
}
instance_of <- function(x, c) {
  k <- if (is.character(c)) K(c) else c
  is.environment(x) && identical(x$.t, "o") && is.environment(k) && identical(k$.t, "c") && is_a(x$.k, k)
}
#' a local written where it was bound, from wherever it is written: the frame that holds the name (R's `<-` would make a new one)
.w <- function(nm, v) {
  force(v)
  start <- parent.frame()
  e <- start
  while (!exists(nm, envir = e, inherits = FALSE)) {
    e <- parent.env(e)
    if (identical(e, RT_TOP) || identical(e, emptyenv())) { e <- start; break }
  }
  assign(nm, v, envir = e)
  invisible(v)
}

# --- what the language's operators are here -----------------------------------------------------
#' what counts as true: everything but None, false, 0, NaN and the empty text - as in TypeScript
truthy <- function(x) {
  if (is.logical(x)) return(length(x) == 1L && !is.na(x) && x)
  if (is.null(x)) return(FALSE)
  if (is.double(x)) return(!is.na(x) && x != 0)
  if (is.character(x)) return(nzchar(x))
  if (is.numeric(x)) return(!is.na(x) && x != 0)
  TRUE
}
and_ <- function(a, b) if (truthy(a)) b else a
or_ <- function(a, b) if (truthy(a)) a else b
or_else <- function(a, b) if (is.null(a)) b else a
num <- function(x) {
  if (is.double(x)) return(x)
  if (is.null(x)) return(0)
  if (is.logical(x)) return(if (isTRUE(x)) 1 else 0)
  if (is.numeric(x)) return(as.double(x))
  NaN
}
arith <- function(a) is.null(a) || is.numeric(a) || is.logical(a)
eq <- function(a, b) {
  if (is.double(a)) return(is.double(b) && length(b) == 1L && !is.na(a == b) && a == b)
  if (is.environment(a)) {
    if (identical(a, b)) return(TRUE)
    if (is.null(b)) return(FALSE)
    ta <- a$.t
    if (ta == "o") { e <- equals_of(a$.k); return(!is.null(e) && truthy(e(a, b))) }
    if (ta == "m") { for (x in a$.i) if (!eq(x, b)) return(FALSE); return(TRUE) }
    if (ta == "l") {
      if (!is_list(b)) return(FALSE)
      x <- a$.v; y <- b$.v
      if (length(x) != length(y)) return(FALSE)
      for (i in seq_along(x)) if (!eq(x[[i]], y[[i]])) return(FALSE)
      return(TRUE)
    }
    return(FALSE)
  }
  if (is.null(a)) return(is.null(b))
  if (is.null(b)) return(FALSE)
  if (is.double(a)) return(is.double(b) && isTRUE(a == b))
  if (is.character(a)) return(is.character(b) && a == b)
  if (is.logical(a)) return(is.logical(b) && identical(a, b))
  if (is.numeric(a)) return(is.numeric(b) && isTRUE(a == b))
  identical(a, b)
}
#' a class's own `equals`, found once (FALSE where it has none)
equals_of <- function(c) {
  e <- c$.eqm
  if (is.null(e)) {
    k <- owner(c, "equals")
    e <- if (!is.null(k) && !is.null(k$.methods[["equals"]])) k$.methods[["equals"]] else FALSE
    c$.eqm <- e
  }
  if (is.function(e)) e else NULL
}
`%||%` <- function(a, b) if (is.null(a)) b else a
#' text joined: what an interpolated text is made of
`%+%` <- function(a, b) paste0(a, b)
lt <- function(a, b) if (is.double(a) && is.double(b)) a < b else if (arith(a)) num(a) < num(b) else if (is.character(a)) a < b else call(a, "lt", b)
le <- function(a, b) if (is.double(a) && is.double(b)) a <= b else if (arith(a)) num(a) <= num(b) else if (is.character(a)) a <= b else call(a, "le", b)
gt <- function(a, b) if (is.double(a) && is.double(b)) a > b else if (arith(a)) num(a) > num(b) else if (is.character(a)) a > b else call(a, "gt", b)
ge <- function(a, b) if (is.double(a) && is.double(b)) a >= b else if (arith(a)) num(a) >= num(b) else if (is.character(a)) a >= b else call(a, "ge", b)
r_add <- function(a, b) {
  if (is.double(a) && is.double(b)) return(a + b)
  if (is.character(a)) return(paste0(a, text_of(b)))
  if (arith(a)) { if (is.character(b)) return(paste0(text_of(a), b)); return(num(a) + num(b)) }
  call(a, "plus", b)
}
r_sub <- function(a, b) if (is.double(a) && is.double(b)) a - b else if (arith(a)) num(a) - num(b) else call(a, "minus", b)
r_mul <- function(a, b) if (is.double(a) && is.double(b)) a * b else if (arith(a)) num(a) * num(b) else call(a, "times", b)
#' a number over nothing is nothing where it is nothing itself, and infinite otherwise - as in TypeScript
r_div <- function(a, b) {
  if (!arith(a)) return(call(a, "over", b))
  x <- num(a); y <- num(b)
  if (y == 0 && !is.na(x) && x == 0) 0 else x / y
}
#' the remainder with the sign of what is divided, as TypeScript's `%`
r_mod <- function(a, b) {
  if (!arith(a)) return(call(a, "mod", b))
  x <- num(a); y <- num(b)
  if (y == 0 || is.infinite(x) || is.na(x) || is.na(y)) return(NaN)
  if (is.infinite(y)) return(x)
  r <- x %% y
  if (r != 0 && (r < 0) != (x < 0)) r - y else r
}
neg <- function(a) if (arith(a)) -num(a) else get(a, "negated")
r_pow <- function(a, b) if (arith(a)) num(a)^num(b) else call(a, "pow", b)

#' a number as TypeScript writes it: the shortest text that reads back as the same number
js_num <- function(x) {
  if (is.nan(x) || is.na(x)) return("NaN")
  if (is.infinite(x)) return(if (x > 0) "Infinity" else "-Infinity")
  if (x == 0) return("0")
  if (x == trunc(x) && abs(x) < 1e21) return(sprintf("%.0f", x))
  s <- NULL
  for (d in 1:17) { s <- sprintf(paste0("%.", d - 1, "e"), x); if (as.numeric(s) == x) break }
  neg_ <- x < 0
  m <- sub("e.*$", "", sub("^-", "", s))
  e <- as.integer(sub("^.*e", "", s))
  digits <- sub("0+$", "", gsub(".", "", m, fixed = TRUE))
  if (!nzchar(digits)) digits <- "0"
  k <- nchar(digits)
  n <- e + 1
  out <- if (k <= n && n <= 21) paste0(digits, strrep("0", n - k))
    else if (0 < n && n <= 21) paste0(substr(digits, 1, n), ".", substr(digits, n + 1, k))
    else if (-6 < n && n <= 0) paste0("0.", strrep("0", -n), digits)
    else {
      ex <- n - 1
      paste0(substr(digits, 1, 1), if (k > 1) paste0(".", substr(digits, 2, k)) else "", "e", if (ex >= 0) "+" else "-", abs(ex))
    }
  if (neg_) paste0("-", out) else out
}
#' a value as text, as the bootstrap writes it: whole numbers without a point, a list its items joined by commas
text_of <- function(x) {
  if (is.character(x)) return(x)
  if (is.double(x)) return(js_num(x))
  if (is.null(x)) return("null")
  if (is.logical(x)) return(if (isTRUE(x)) "true" else "false")
  if (is.environment(x)) {
    tt <- x$.t
    if (tt == "l") return(paste(vapply(x$.v, text_of, ""), collapse = ","))
    if (tt == "m") return(paste(vapply(x$.i, text_of, ""), collapse = ","))
    if (tt == "c") return(x$.name)
    if (tt == "o") { k <- owner(x$.k, "toString"); if (!is.null(k) && !is.null(k$.methods[["toString"]])) return(text_of(call(x, "toString"))); return(x$.k$.name) }
  }
  if (is.numeric(x)) return(js_num(as.double(x)))
  if (is.function(x)) return("function")
  paste(as.character(x), collapse = ",")
}

# --- lists and text -------------------------------------------------------------------------------
as_list <- function(v) { l <- new.env(parent = emptyenv()); l$.t <- "l"; l$.v <- v; l }
#' `[a, b]`: a list, shared by everyone holding it
lst <- function(...) as_list(list(...))
is_list <- function(x) is.environment(x) && identical(x$.t, "l")
#' what a list, a Many or a text holds, as an R list (a copy: what it is iterated over is not changed by what the loop does)
items <- function(xs) {
  if (is.environment(xs)) {
    tt <- xs$.t
    if (tt == "l") return(xs$.v)
    if (tt == "m") return(xs$.i)
  }
  if (is.character(xs)) return(as.list(strsplit(xs, "")[[1]]))
  if (is.null(xs)) return(list())
  stop(paste0("not a list: ", text_of(xs)))
}
len <- function(xs) {
  if (is.environment(xs)) {
    tt <- xs$.t
    if (tt == "l") return(length(xs$.v))
    if (tt == "m") return(length(xs$.i))
    return(get(xs, "length"))
  }
  if (is.character(xs)) return(as.double(nchar(xs)))
  if (is.null(xs)) stop("no member length on None")
  get(xs, "length")
}
#' `x[k]`: an element of a list (negative from the end), or a member by its name
elem <- function(t, k) {
  if (is.environment(t)) {
    v <- t$.v
    if (!is.null(v)) {
      if (!is.double(k)) { if (is.null(k) || is.character(k)) return(NULL); k <- num(k) }
      n <- length(v)
      if (k < 0) k <- k + n
      if (k >= 0 && k < n) return(.subset2(v, k + 1))
      return(NULL)
    }
    tt <- t$.t
    if (tt == "o" || tt == "c") { if (is.null(k)) return(NULL); return(get(t, key_(k))) }
    if (tt == "m") return(collapse(lapply(t$.i, function(x) elem(x, k))))
  }
  if (is.character(t)) {
    if (!is.numeric(k)) return(NULL)
    n <- nchar(t)
    if (k < 0) k <- k + n
    if (k >= 0 && k < n) return(substr(t, k + 1, k + 1))
    return(NULL)
  }
  NULL
}
set_at <- function(t, k, v) {
  if (is.environment(t) && identical(t$.t, "l")) {
    # what is written is read first (R's arguments are read when used: after the list is taken out, it would read an empty one);
    # then the list taken out of its environment, so that R changes it in place instead of copying it
    force(v)
    i <- num(k) + 1
    l <- t$.v
    t$.v <- NULL
    l[i] <- list(v)
    t$.v <- l
    return(v)
  }
  set(t, key_(k), v)
}
#' a key of a map as a name: R names no variable "", so the empty key is kept under one R never writes
key_ <- function(k) { k <- if (is.character(k)) k else text_of(k); if (nzchar(k)) k else "\001" }
push <- function(xs, x) { force(x); l <- xs$.v; xs$.v <- NULL; l[length(l) + 1] <- list(x); xs$.v <- l; xs }
filt <- function(xs, f, ...) {
  if (is.environment(xs) && identical(xs$.t, "m")) return(many_of(Filter(function(x) truthy(f(x)), xs$.i)))
  as_list(Filter(function(x) truthy(f(x)), items(xs)))
}
rng <- function(n) { k <- ceiling(num(n)); as_list(if (k > 0) as.list(seq_len(k) - 1) else list()) }
filled <- function(n, v) { k <- ceiling(num(n)); as_list(if (k > 0) rep(list(v), k) else list()) }
#' a block taken apart by `for`: each turn a call of its own; a turn that returned hands out what it returned (in a list) and stops the loop
for_each <- function(xs, f) {
  for (x in items(xs)) { r <- f(x); if (!is.symbol(r)) return(list(r)) }
  NULL
}
for_range <- function(n, f) {
  k <- ceiling(num(n))
  if (k > 0) for (i in seq_len(k) - 1) { r <- f(i); if (!is.symbol(r)) return(list(r)) }
  NULL
}
contains <- function(xs, x) {
  if (is.character(xs)) return(grepl(text_of(x), xs, fixed = TRUE))
  for (y in items(xs)) if (eq(y, x)) return(TRUE)
  FALSE
}
index_of <- function(xs, x) {
  if (is.character(xs)) { i <- regexpr(text_of(x), xs, fixed = TRUE)[1]; return(if (i < 0) NULL else as.double(i - 1)) }
  l <- items(xs)
  for (i in seq_along(l)) if (eq(l[[i]], x)) return(as.double(i - 1))
  NULL
}
first <- function(xs) { if (is.character(xs)) return(if (nzchar(xs)) substr(xs, 1, 1) else NULL); l <- items(xs); if (length(l)) l[[1]] else NULL }
last <- function(xs) { if (is.character(xs)) { n <- nchar(xs); return(if (n) substr(xs, n, n) else NULL) }; l <- items(xs); if (length(l)) l[[length(l)]] else NULL }
join <- function(xs, sep) paste(vapply(items(xs), text_of, ""), collapse = text_of(sep))
#' a text in double quotes, as JSON writes it
quoted <- function(x) {
  s <- text_of(x)
  s <- gsub("\\", "\\\\", s, fixed = TRUE)
  s <- gsub("\"", "\\\"", s, fixed = TRUE)
  s <- gsub("\n", "\\n", s, fixed = TRUE)
  s <- gsub("\r", "\\r", s, fixed = TRUE)
  s <- gsub("\t", "\\t", s, fixed = TRUE)
  paste0("\"", s, "\"")
}
most <- function(xs, key) {
  l <- items(xs)
  best <- NULL; at_ <- -1; bk <- -Inf
  for (i in seq_along(l)) { k <- num(key(l[[i]])); if (is.null(best) || k > bk) { best <- l[[i]]; at_ <- i - 1; bk <- k } }
  if (is.null(best)) NULL else lst(best, as.double(at_))
}
sorted_by <- function(xs, key) {
  l <- items(xs)
  if (!length(l)) return(as_list(list()))
  k <- vapply(l, function(x) num(key(x)), 0)
  as_list(l[order(k, seq_along(l), method = "radix")])
}
summed <- function(xs) { s <- 0; for (x in items(xs)) s <- s + num(x); s }
fail <- function(says) stop(text_of(says))
codepoints <- function(s) as_list(as.list(as.double(utf8ToInt(s))))
from_codepoints <- function(xs) intToUtf8(vapply(items(xs), function(c) as.integer(num(c)), 0L))
blank <- function(c) { d <- num(c); d == 32 || d == 9 || d == 10 || d == 13 }
number <- function(s) { v <- suppressWarnings(as.numeric(trimws(text_of(s)))); if (is.na(v)) NaN else v }

#' a member Ray knows on a list, a text or a number - and any object's own member of that name otherwise (`Expr.split(e, name)`)
core <- function(x) !is.environment(x) || identical(x$.t, "l") || identical(x$.t, "m")
m_push <- function(xs, ...) if (core(xs)) push(xs, ..1) else call(xs, "push", ...)
m_chars <- function(xs) if (is.character(xs)) codepoints(xs) else get(xs, "chars")
m_pop <- function(xs) {
  if (!core(xs)) return(get(xs, "pop"))
  n <- length(xs$.v)
  if (!n) return(NULL)
  l <- xs$.v
  xs$.v <- NULL
  x <- l[[n]]
  length(l) <- n - 1
  xs$.v <- l
  x
}
m_map <- function(xs, ...) { if (!core(xs)) return(call(xs, "map", ...)); f <- ..1; as_list(lapply(items(xs), function(x) f(x))) }
m_for <- function(xs, ...) { if (!core(xs)) return(call(xs, "for", ...)); f <- ..1; for (x in items(xs)) f(x); NULL }
m_some <- function(xs, ...) { if (!core(xs)) return(call(xs, "some", ...)); f <- ..1; for (x in items(xs)) if (truthy(f(x))) return(TRUE); FALSE }
m_every <- function(xs, ...) { if (!core(xs)) return(call(xs, "every", ...)); f <- ..1; for (x in items(xs)) if (!truthy(f(x))) return(FALSE); TRUE }
m_reduce <- function(xs, ...) { if (!core(xs)) return(call(xs, "reduce", ...)); acc <- ..1; f <- ..2; for (x in items(xs)) acc <- f(acc, x); acc }
m_starts_with <- function(xs, ...) if (core(xs)) startsWith(xs, text_of(..1)) else call(xs, "starts_with", ...)
m_ends_with <- function(xs, ...) if (core(xs)) endsWith(xs, text_of(..1)) else call(xs, "ends_with", ...)
m_replace <- function(xs, ...) if (core(xs)) gsub(text_of(..1), text_of(..2), xs, fixed = TRUE) else call(xs, "replace", ...)
m_split <- function(xs, ...) {
  if (!core(xs)) return(call(xs, "split", ...))
  sep <- text_of(..1)
  if (!nzchar(sep)) return(as_list(items(xs)))
  as_list(as.list(strsplit(paste0(xs, sep), sep, fixed = TRUE)[[1]]))
}
m_trim <- function(xs) if (core(xs)) trimws(xs) else get(xs, "trim")
m_upper <- function(xs) if (core(xs)) toupper(xs) else get(xs, "upper")
m_lower <- function(xs) if (core(xs)) tolower(xs) else get(xs, "lower")
m_lines <- function(xs) if (core(xs)) m_split(xs, "\n") else get(xs, "lines")
m_contains <- function(xs, ...) if (core(xs)) contains(xs, ..1) else call(xs, "contains", ...)
m_index_of <- function(xs, ...) if (core(xs)) index_of(xs, ..1) else call(xs, "index_of", ...)
m_join <- function(xs, ...) if (core(xs)) join(xs, ..1) else call(xs, "join", ...)
m_first <- function(xs) if (core(xs)) first(xs) else get(xs, "first")
m_last <- function(xs) if (core(xs)) last(xs) else get(xs, "last")
m_empty <- function(xs) if (core(xs)) len(xs) == 0 else get(xs, "empty")
m_take <- function(xs, ...) {
  if (!core(xs)) return(call(xs, "take", ...))
  k <- num(..1)
  if (is.character(xs)) return(substr(xs, 1, max(0, k)))
  l <- items(xs)
  as_list(l[seq_len(max(0, min(k, length(l))))])
}
m_drop <- function(xs, ...) {
  if (!core(xs)) return(call(xs, "drop", ...))
  k <- num(..1)
  if (is.character(xs)) return(substr(xs, max(0, k) + 1, nchar(xs)))
  l <- items(xs)
  k <- max(0, min(k, length(l)))
  as_list(if (k >= length(l)) list() else l[(k + 1):length(l)])
}
m_rest <- function(xs) if (core(xs)) m_drop(xs, 1) else get(xs, "rest")
m_concat <- function(xs, ...) {
  if (!core(xs)) return(call(xs, "concat", ...))
  ys <- ..1
  if (is.character(xs)) return(paste0(xs, text_of(ys)))
  as_list(c(items(xs), items(ys)))
}
m_reverse <- function(xs) {
  if (!core(xs)) return(get(xs, "reverse"))
  if (is.character(xs)) return(intToUtf8(rev(utf8ToInt(xs))))
  as_list(rev(items(xs)))
}
m_sum <- function(xs) if (core(xs)) summed(xs) else get(xs, "sum")
m_most <- function(xs, ...) if (core(xs)) most(xs, ..1) else call(xs, "most", ...)
m_sorted_by <- function(xs, ...) if (core(xs)) sorted_by(xs, ..1) else call(xs, "sorted_by", ...)
m_each <- function(xs) if (core(xs)) many_of(items(xs)) else get(xs, "each")
m_sqrt <- function(x) if (arith(x)) { v <- num(x); if (v < 0 || is.na(v)) NaN else sqrt(v) } else get(x, "sqrt")
m_floor <- function(x) if (arith(x)) floor(num(x)) else get(x, "floor")
m_abs <- function(x) if (arith(x)) abs(num(x)) else get(x, "abs")
m_magnitude <- function(x) if (arith(x)) abs(num(x)) else get(x, "magnitude")
m_cos <- function(x) if (arith(x)) cos(num(x)) else get(x, "cos")
m_sin <- function(x) if (arith(x)) sin(num(x)) else get(x, "sin")
m_round <- function(x) if (arith(x)) floor(num(x) + 0.5) else get(x, "round")
m_ln <- function(x) if (arith(x)) { v <- num(x); if (is.na(v) || v < 0) NaN else log(v) } else get(x, "ln")
m_exp <- function(x) if (arith(x)) exp(num(x)) else get(x, "exp")
m_atan2 <- function(x, ...) if (arith(x)) atan2(num(x), num(..1)) else call(x, "atan2", ...)
m_pow <- function(x, ...) if (arith(x)) num(x)^num(..1) else call(x, "pow", ...)

# --- the Many: a superposition; members apply elementwise, equal things collapse ---------------------
many_of <- function(l) { m <- new.env(parent = emptyenv()); m$.t <- "m"; m$.i <- l; m }
many <- function(xs) many_of(items(xs))
collapse <- function(l) {
  if (!length(l)) return(many_of(l))
  f <- l[[1]]
  for (i in l) if (!(identical(i, f) || (is_list(i) && is_list(f) && eq(i, f)))) return(many_of(l))
  f
}
